/*!50003 DROP FUNCTION IF EXISTS `D032_Tipo` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_uca1400_ai_ci */ ;
DELIMITER ;;
CREATE DEFINER=`fixar`@`%` FUNCTION `D032_Tipo`(xTipo int(2)) RETURNS varchar(30) CHARSET latin1 COLLATE latin1_swedish_ci
BEGIN
    DECLARE xDescricao VARCHAR(25);
    SET xDescricao = '';

    IF xTipo=1 THEN
        SET xDescricao = '01-RECEITAS';
    END IF;
    IF xTipo=10 THEN
        SET xDescricao = '10-FIXAS';
    END IF;
    IF xTipo=20 THEN
        SET xDescricao = '20-VARIAVEIS';
    END IF;
    IF xTipo=25 THEN
        SET xDescricao = '25-FORNECEDORES';
    END IF;
    IF xTipo=30 THEN
        SET xDescricao = '30-INVESTIMENTOS';
    END IF;
    IF xTipo=40 THEN
        SET xDescricao = '40-SOCIOS';
    END IF;
    IF xTipo=50 THEN
        SET xDescricao = '50-OUTROS';
    END IF;

    RETURN xDescricao;
END
;;
DELIMITER ;
